mapper.select:

WHERE c.organization_id = #{organizationId}
  AND c.id = #{leadId}
  AND c.deleted_at IS NULL
  AND (c.stage = 'LEAD' OR c.attributes ->> 'leadOrigin' = 'true')
LIMIT 1

SELECT COUNT(DISTINCT c.id)
FROM customer c
LEFT JOIN customer_contact contact
  ON contact.organization_id = c.organization_id AND contact.customer_id = c.id AND contact.deleted_at IS NULL
WHERE c.organization_id = #{organizationId}
  AND c.deleted_at IS NULL

  AND c.id <> #{excludeId}

  AND (lower(c.name) = lower(#{company})

    OR lower(contact.email) = lower(#{email})


    OR contact.phone = #{phone}

  )
